    public LoanApplication testCreate() throws Throwable {
    LoanApplication entity = null;

    LOGGER.info( "LoanApplicationTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a LoanApplication");

    StringBuilder msg = new StringBuilder( "-- Failed to create a LoanApplication" );

    try {
        entity = service.createLoanApplication( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getLoanApplicationId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a LoanApplication with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

