    /**
     * Tests getting all LoanApplications.
     *
     * @return    Collection
     */
    public List<LoanApplication> testGetAll() throws Throwable {
    LOGGER.info( "LoanApplicationTest:testGetAll() - Retrieving Collection of LoanApplications:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all LoanApplication : " );
    List<LoanApplication> collection  = null;

    try {
        // call the static get method on the LoanApplicationService
        collection = service.getAllLoanApplication();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            LoanApplication currEntity  = null;
            Iterator<LoanApplication> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getLoanApplicationId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

